// Browser BDD test: a Chromium/Firefox page running the JS
// grpc-dc client over a native RTCDataChannel executes the full
// generated BDD scenario table (including failure, deadline,
// cancellation, and stream-break) against a gRPC server on the
// Node WebRTC stack. The scenario table is generated by
// grpc-dc codegen; the in-page interpreter is bdd_runner.mjs.

import assert from "node:assert/strict";
import { join } from "node:path";
import { launchBrowser, newPage, runEngines, startStaticServer } from "./harness.mjs";

import { Peer } from "../webrtc/js/peer.js";
import { Server, StatusCode, StatusError } from "../js/index.js";
import { EchoResponse } from "../js/examples/echo_pb.js";
import { createEchoService } from "../js/examples/echo_grpc_dc.js";
import { BDD_SCENARIOS } from "./bdd_scenarios.generated.mjs";

const { server, pageUrl } = await startStaticServer("browser-test/bdd_page.html");

// Canonical Echo semantics (the BDD specification): "fail" is
// rejected in every method, delayMs delays unary, x-echo
// metadata is reflected in the unary reply. ServerStream counts
// production into `state` and paces it (~10ms/response) so the
// stream-break scenario can observe the server stopping after
// the browser client abandons the stream.
function makeHandlers(state) {
  return {
    async unary(req, ctx) {
      if (req.message === "fail") {
        throw new StatusError(StatusCode.INVALID_ARGUMENT, "asked to fail");
      }
      if (req.delayMs > 0) {
        await new Promise((r) => setTimeout(r, req.delayMs));
      }
      const suffix = ctx.metadata["x-echo"] ? ` [${ctx.metadata["x-echo"]}]` : "";
      if (ctx.metadata["x-echo-trailer"]) {
        ctx.setTrailers({ "x-echo-trailer": ctx.metadata["x-echo-trailer"] });
      }
      return new EchoResponse({ message: `echo: ${req.message}${suffix}`, index: 0 });
    },
    async *serverStream(req) {
      if (req.message === "fail") {
        throw new StatusError(StatusCode.INVALID_ARGUMENT, "asked to fail");
      }
      for (let i = 0; i < Math.max(0, req.count); i++) {
        state.produced++;
        yield new EchoResponse({ message: req.message, index: i });
        await new Promise((r) => setTimeout(r, 10));
      }
    },
    async clientStream(requests) {
      const parts = [];
      for await (const req of requests) parts.push(req.message);
      return new EchoResponse({ message: parts.join("+"), index: parts.length });
    },
    async *bidi(requests) {
      let index = 0;
      for await (const req of requests) {
        if (req.message === "fail") {
          throw new StatusError(StatusCode.INVALID_ARGUMENT, "asked to fail");
        }
        yield new EchoResponse({ message: req.message, index: index++ });
      }
    },
  };
}

async function runBrowser(name) {
  const answerer = await Peer.create();
  const browser = await launchBrowser(name);
  try {
    const state = { produced: 0 };
    const grpcServer = new Server();
    grpcServer.addService(createEchoService(makeHandlers(state)));

    const page = await browser.newPage();
    // Bridge for the stream-break scenario: the in-page runner
    // reads the Node server's production count through this.
    await page.exposeFunction("__bddProduced", () => state.produced);
    page.on("console", (msg) => console.log(`[${name} console] ${msg.text()}`));
    page.on("pageerror", (err) => console.log(`[${name} pageerror] ${err.message}`));
    await page.goto(pageUrl);
    await page.waitForFunction(() => window.__offer, null, { timeout: 30000 });

    const offer = await page.evaluate(() => window.__offer);
    const answer = answerer.handleOffer(offer);
    await page.evaluate((sdp) => window.__acceptAnswer(sdp), answer);

    const endpoint = await answerer.connect();
    endpoint.onchannel = (channel) => grpcServer.serve(channel);

    const results = await page.evaluate(() => window.__runBdd());
    assert.equal(results.length, BDD_SCENARIOS.length,
      `${name}: expected ${BDD_SCENARIOS.length} scenario results`);
    const failed = results.filter((r) => !r.ok);
    assert.equal(failed.length, 0,
      `${name}: BDD failures:\n${failed.map((r) => `${r.name}: ${r.detail}`).join("\n")}`);
    console.log(`${name}: browser BDD over native RTCDataChannel OK (${results.length} scenarios)`);
  } finally {
    await browser.close();
    await answerer.close();
  }
}

await runEngines(process.argv[2], runBrowser);

server.close();
console.log("browser BDD test passed");
